effect.shader:
float canalDir(vec2 uv, float ang, float l, int n, int ch) {
    vec2 dir = vec2(cos(ang), sin(ang));
    dir.x /= acAspect;
    float soma = 0.0;
    for (int i = 0; i <= 32; i++) {
        if (i > n) break;
        float t = float(i) / float(n) - 0.5;
        soma += texture(inputImg, uv + dir * l * t)[ch];
    }
    return soma / float(n + 1);
}

void main() {
    if (len <= 0.0) { fragColor = texture(inputImg, acScreenNorm); return; }
    int n = clamp(int(samples), 4, 32);
    float base = radians(angle);
    float dA = radians(spread);
    float r = canalDir(acScreenNorm, base - dA, len, n, 0);
    float g = canalDir(acScreenNorm, base,       len, n, 1);
    float b = canalDir(acScreenNorm, base + dA, len, n, 2);
    float a = texture(inputImg, acScreenNorm).a;
    fragColor = vec4(r, g, b, a);
}
